commands.ac1:
root=$(git rev-parse --show-toplevel 2>/dev/null) || root=.
cd "$root" || { echo "FAIL AC-1: cannot cd to the repo root"; exit 1; }
[ -f _docs/openapi.yaml ] || { echo "FAIL AC-1: not run from the TableQueue repo root (_docs/openapi.yaml missing)"; exit 1; }
[ -x backend/.venv/Scripts/python.exe ] || { echo "FAIL AC-1: not measured - backend/.venv/Scripts/python.exe is missing (create the suite venv: cd backend && uv sync)"; exit 1; }
mkdir -p backend/.scratch
rm -f backend/.scratch/t16ac1.db
( cd backend && ENV=development DATABASE_URL="sqlite:///.scratch/t16ac1.db" JWT_SECRET="t16ac1-secret-0123456789-abcdefghijklmnopqrstuvwxyz" STAFF_PIN=0000 TZ=UTC \
.venv/Scripts/python.exe - <<'PY'
import os, re, sys
sys.path.insert(0, '.')

LEGACY = [
    # (name, normalised legacy path, verb the client spells, full literal, base-stripped call expression)
    ('/public/board/{id}', '/api/v1/public/board/*', 'get', '/api/v1/public/board', r"get\(['\"]/public/board"),
    ('/staff/login', '/api/v1/staff/login', 'post', '/api/v1/staff/login', r"post\(['\"]/staff/login"),
    ('/staff/pin/change', '/api/v1/staff/pin/change', 'post', '/api/v1/staff/pin/change', r"post\(['\"]/staff/pin/change"),
]

def norm(p):
    return re.sub(r'\{[^}]+\}', '*', p)

try:
    from app.main import app
except Exception as exc:
    print('FAIL AC-1: not measured - app.main import failed: ' + str(exc)[:160])
    raise SystemExit(1)

def walk(routes, depth=0):
    if depth > 8:
        return
    for rt in routes:
        yield rt
        for attr in ('routes', 'original_router'):
            n = getattr(rt, attr, None)
            if n is None:
                continue
            if isinstance(n, (list, tuple)):
                yield from walk(n, depth + 1)
            elif hasattr(n, 'routes'):
                yield from walk([n], depth + 1)

served = set()
for rt in walk(app.routes):
    p = getattr(rt, 'path', None)
    methods = getattr(rt, 'methods', None) or set()
    if isinstance(p, str):
        for verb in methods:
            if verb.upper() in ('GET', 'POST', 'PATCH', 'PUT', 'DELETE'):
                served.add((norm(p), verb.upper()))

try:
    import yaml
    contract = yaml.safe_load(open('../_docs/openapi.yaml', encoding='utf-8').read())
except Exception as exc:
    print('FAIL AC-1: not measured - _docs/openapi.yaml does not parse: ' + str(exc)[:120])
    raise SystemExit(1)
cpaths = contract.get('paths') or {}

def resolve(node, depth=0):
    if isinstance(node, dict) and set(node) == {'$ref'} and depth < 5:
        cur = contract
        for part in node['$ref'].lstrip('#/').split('/'):
            cur = cur.get(part) if isinstance(cur, dict) else None
        if cur is None:
            return None
        return resolve(cur, depth + 1)
    return node

specs = open('../_docs/specs.md', encoding='utf-8').read()

refs = {}
for dirpath, dirnames, filenames in os.walk('../frontend'):
    dirnames[:] = [d for d in dirnames if d != 'node_modules']
    for fn in filenames:
        fp = os.path.join(dirpath, fn)
        try:
            with open(fp, 'r', encoding='utf-8', errors='replace') as fh:
                for i, line in enumerate(fh, 1):
                    for idx in range(3):
                        literal = LEGACY[idx][3]
                        if literal in line or re.search(LEGACY[idx][4], line):
                            refs.setdefault(idx, []).append('%s:%d' % (os.path.relpath(fp, os.path.pardir).replace(os.sep, '/'), i))
        except (OSError, UnicodeDecodeError):
            pass

problems, resolved = [], []
for idx, (name, lnorm, verb, literal, expr) in enumerate(LEGACY):
    match = None
    for cpath, citem in cpaths.items():
        if norm(cpath) != lnorm:
            continue
        op = (citem or {}).get(verb)
        if op is None:
            continue
        res = op.get('responses') or {}
        if not res:
            continue
        ok = True
        for code, r in res.items():
            full = resolve(r) or {}
            if not str(full.get('description') or '').strip():
                ok = False
                break
        if not ok:
            continue
        if cpath not in specs:
            continue
        if (lnorm, verb.upper()) not in served:
            continue
        match = cpath
        break
    if match:
        resolved.append('%s: EXISTS (%s documented in openapi.yaml and specs.md, served as %s)' % (name, match, verb.upper()))
        continue
    hit = refs.get(idx)
    if hit:
        problems.append('%s: neither implemented nor stopped - %d frontend reference(s), e.g. %s' % (name, len(hit), '; '.join(hit[:4])))
    else:
        resolved.append('%s: STOPPED (no frontend reference to %s or to the base-stripped %s() call)' % (name, literal, verb))
if problems:
    print('FAIL AC-1: ' + '; '.join(problems))
    raise SystemExit(1)
print('PASS AC-1: ' + '; '.join(resolved))
PY
)
rc=$?
rm -f backend/.scratch/t16ac1.db
rmdir backend/.scratch 2>/dev/null
exit $rc

commands.ac2:
root=$(git rev-parse --show-toplevel 2>/dev/null) || root=.
cd "$root" || { echo "FAIL AC-2: cannot cd to the repo root"; exit 1; }
[ -f _docs/openapi.yaml ] || { echo "FAIL AC-2: not run from the TableQueue repo root (_docs/openapi.yaml missing)"; exit 1; }
[ -x backend/.venv/Scripts/python.exe ] || { echo "FAIL AC-2: not measured - backend/.venv/Scripts/python.exe is missing (create the suite venv: cd backend && uv sync)"; exit 1; }
backend/.venv/Scripts/python.exe - <<'PY'
import re, sys

try:
    import yaml
except Exception as exc:
    print('FAIL AC-2: not measured - no YAML parser in backend/.venv: ' + str(exc)[:120])
    raise SystemExit(1)

OPS = [
    ('/api/v1/branches/{branch_id}/waitlist', 'post'),
    ('/api/v1/staff/waitlist/{id}/seat', 'post'),
]

try:
    contract = yaml.safe_load(open('_docs/openapi.yaml', encoding='utf-8').read())
except Exception as exc:
    print('FAIL AC-2: not measured - _docs/openapi.yaml does not parse: ' + str(exc)[:120])
    raise SystemExit(1)

def resolve(node, depth=0):
    if isinstance(node, dict) and set(node) == {'$ref'} and depth < 5:
        cur = contract
        for part in node['$ref'].lstrip('#/').split('/'):
            cur = cur.get(part) if isinstance(cur, dict) else None
        if cur is None:
            return None
        return resolve(cur, depth + 1)
    return node

problems = []
for path, verb in OPS:
    op = ((contract.get('paths') or {}).get(path) or {}).get(verb)
    r422 = (op or {}).get('responses', {}).get('422') if isinstance(op, dict) else None
    if r422 is None:
        problems.append('%s %s declares no 422 response' % (verb.upper(), path))
        continue
    full = resolve(r422) or {}
    schema = ((full.get('content') or {}).get('application/json') or {}).get('schema')
    schema = resolve(schema)
    if not isinstance(schema, dict) or 'error' not in (schema.get('required') or []):
        problems.append('%s %s 422 does not resolve to the error envelope (top-level required error)' % (verb.upper(), path))
        continue
    err = (schema.get('properties') or {}).get('error') or {}
    if not {'code', 'message'} <= set(err.get('required') or []):
        problems.append('%s %s 422 envelope error lacks required code+message' % (verb.upper(), path))

lines = open('_docs/specs.md', encoding='utf-8').read().splitlines()
RE422 = re.compile(r'(?<!\d)422(?!\d)')

def window_ok(start):
    w = lines[start:start + 40]
    has422 = any(RE422.search(l) for l in w)
    hascode = any('VALIDATION_ERROR' in l for l in w)
    json_form = any('"error"' in l for l in w) and any('"code"' in l for l in w) and any('"message"' in l for l in w)
    prose_form = any('error.code' in l for l in w) and any('error.message' in l for l in w)
    return has422 and hascode and (json_form or prose_form)

for path, verb in OPS:
    idxs = [i for i, l in enumerate(lines) if path in l]
    if not idxs:
        problems.append('specs.md never names %s' % path)
        continue
    if not any(window_ok(i) for i in idxs):
        problems.append('specs.md has no 422 VALIDATION_ERROR envelope body within 40 lines of any %s line (first at line %d)' % (path, idxs[0] + 1))

if problems:
    print('FAIL AC-2: ' + '; '.join(problems))
    raise SystemExit(1)
print('PASS AC-2: both operations (POST /api/v1/branches/{branch_id}/waitlist, POST /api/v1/staff/waitlist/{id}/seat) declare a 422 that resolves to the error envelope in openapi.yaml, and specs.md documents the 422 VALIDATION_ERROR envelope body within 40 lines of each operation')
PY

