.venv/Scripts/python.exe - <<'PY'
import re, sys
sys.path.insert(0, '.')

try:
    import yaml
    contract = yaml.safe_load(open('../_docs/openapi.yaml', encoding='utf-8').read())
except Exception as exc:
    print('FAIL AC-3: not measured - _docs/openapi.yaml does not parse or no YAML parser: ' + str(exc)[:120])
    raise SystemExit(1)

def norm(p):
    return re.sub(r'\{[^}]+\}', '*', p)

def resolve(node, depth=0):
    if isinstance(node, dict) and set(node) == {'$ref'} and depth < 5:
        cur = contract
        for part in node['$ref'].lstrip('#/').split('/'):
            cur = cur.get(part) if isinstance(cur, dict) else None
        if cur is None:
            return None
        return resolve(cur, depth + 1)
    return node

try:
    from app.main import app
except Exception as exc:
    print('FAIL AC-3: not measured - app.main import failed: ' + str(exc)[:160])
    raise SystemExit(1)

def walk(routes, depth=0):
    if depth > 8:
        return
    for rt in routes:
        yield rt
        for attr in ('routes', 'original_router'):
            n = getattr(rt, attr, None)
            if n is None:
                continue
            if isinstance(n, (list, tuple)):
                yield from walk(n, depth + 1)
            elif hasattr(n, 'routes'):
                yield from walk([n], depth + 1)

served = set()
for rt in walk(app.routes):
    p = getattr(rt, 'path', None)
    methods = getattr(rt, 'methods', None) or set()
    if isinstance(p, str):
        for verb in methods:
            if verb.upper() in ('GET', 'POST', 'PATCH', 'PUT', 'DELETE'):
                served.add((norm(p), verb.upper()))

specs = open('../_docs/specs.md', encoding='utf-8').read()
VERBS = ('get', 'post', 'patch', 'put', 'delete')

endpoint_found = None
for cpath, citem in (contract.get('paths') or {}).items():
    if 'close' not in cpath.lower():
        continue
    for verb, op in (citem or {}).items():
        if verb not in VERBS or not isinstance(op, dict):
            continue
        res = op.get('responses') or {}
        if not res:
            continue
        ok = True
        for code, r in res.items():
            if not str((resolve(r) or {}).get('description') or '').strip():
                ok = False
                break
        if not ok:
            continue
        text = '%s %s' % (op.get('summary') or '', op.get('description') or '')
        if not re.search(r'(?i)(close|day)', text):
            continue
        if cpath not in specs:
            continue
        if (norm(cpath), verb.upper()) not in served:
            continue
        endpoint_found = '%s %s' % (verb.upper(), cpath)
        break
    if endpoint_found:
        break

RE_CLOSE = re.compile(r'(?i)close.{0,3}day')
RE_MARKER = re.compile(r'(?i)(out[- ]of[- ](the )?(api )?contract|outside the (api )?contract|not (part of|in) the (api )?contract|no (api )?(endpoint|operation|route)s?\b)')
lines = specs.splitlines()
ooc = None
for i, l in enumerate(lines):
    if not RE_CLOSE.search(l):
        continue
    w = lines[i:i + 25]
    m = [x for x in w if RE_MARKER.search(x)]
    if m:
        ooc = 'line %d: %s' % (i + 1, m[0].strip()[:80])
        break

if endpoint_found:
    print('PASS AC-3: Close-Day is a documented, served endpoint: %s (openapi.yaml + specs.md + served route table)' % endpoint_found)
elif ooc:
    print('PASS AC-3: Close-Day is explicitly out of the API contract in specs.md (%s)' % ooc)
else:
    close_lines = [i + 1 for i, l in enumerate(lines) if RE_CLOSE.search(l)][:6]
    print('FAIL AC-3: neither arm holds - no close path in openapi.yaml and no explicit out-of-contract marker within 25 lines of any close-day line in specs.md (close-day lines: %s)' % close_lines)
    raise SystemExit(1)
PY
)
